WITH x AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, COALESCE(NULLIF(TAHUN_TANAM,''),'-') thn, CASE WHEN UPPER(MATURITY_STATUS) LIKE 'TM%' THEN 'TM' WHEN REPLACE(UPPER(MATURITY_STATUS),' ','') IN ('TBM2','TBM3') THEN 'TBM' ELSE 'X' END kind, DATE_TRUNC('month',BULAN)::DATE mo, SUM(HEKTAR) ha FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE KODE_BA IN ('2121','2124','2131','2122') AND KATEGORI_TANAH='PLANTED' AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2,3,4,5) SELECT ba, afd, thn, kind, ROUND(SUM(IFF(mo<'2026-09-01',ha,0)),2) ha_a, ROUND(SUM(IFF(mo='2026-09-01',ha,0)),2) ha_m FROM x GROUP BY 1,2,3,4 HAVING SUM(ha)>0 ORDER BY 1,2,3,4